// Writes docs/commands.md from the command definitions, so the docs cannot drift from the code.
import { writeFileSync } from "node:fs";

import { modules } from "#app/modules.ts";
import { usage } from "#core/commands/values.ts";

const lines = [
  "# Commands",
  "",
  "Generated by `npm run docs:commands`. Do not edit by hand.",
  "",
  "Every command works as a slash command and with the server's prefix (default `-`).",
  "",
];

for (const module of modules) {
  const commands = (module.commands ?? []).filter((command) => !command.ownerOnly);
  const menus = module.contextMenus ?? [];
  if (commands.length === 0 && menus.length === 0) continue;
  lines.push(`## ${module.name}`, "", "| Command | Description | Also works as |", "|---|---|---|");
  for (const command of commands) {
    for (const [name, leaf] of command.leaves) {
      const path = name === "" ? command.name : `${command.name} ${name}`;
      const isDefault = name === "" || name === command.defaultSubcommand;
      const aliases = [...leaf.aliases, ...(isDefault ? command.aliases : [])];
      const also = aliases.map((alias) => `\`-${alias}\``).join(", ");
      lines.push(`| \`${usage("/", path, leaf.options)}\` | ${leaf.description} | ${also} |`);
    }
  }
  for (const menu of menus) {
    lines.push(`| ${menu.name} (right-click a ${menu.type}, then Apps) | | |`);
  }
  lines.push("");
}

writeFileSync("docs/commands.md", lines.join("\n"));
console.log("Wrote docs/commands.md");
